(() => {
'use strict';
const $=s=>document.querySelector(s),N=560,core=PaperFoldCore,config=PAPER_CUTTING_ASSETS,canvas=$('#fold-canvas'),ctx=canvas.getContext('2d');
const names=['选样折纸','循线剪刻','展纸成花'],colors=['#ce3027','#e9dfc8','#efa99f'];
let pattern,model,stage=0,paperColor=0,fold=0,unfold=100,zoom=100,mount='paper',tool='scissors',strokes=[],current=null,pressed=false,loadToken=0,ready=false,anim=0;
let keyboard={x:410,y:280};
const key=()=>`santai:fold:v2:${pattern.id}`;
function persist(){if(!ready)return;try{sessionStorage.setItem(key(),JSON.stringify({stage,paperColor,fold,unfold,mount,strokes}));}catch{}}
function status(s){$('#fold-status').textContent=s;}
function image(path){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=window.PAPER_CUTTING_IMAGES?.[path]||path;});}
function layer(){const c=document.createElement('canvas');c.width=c.height=N;return c;}
function colored(mask){const c=layer(),g=c.getContext('2d'),d=g.createImageData(N,N),hex=colors[paperColor],rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));for(let i=0;i<mask.length;i++)if(mask[i]){const grain=((i*13+i%N*7)%11)-5;for(let k=0;k<3;k++)d.data[i*4+k]=rgb[k]+grain;d.data[i*4+3]=255;}g.putImageData(d,0,0);return c;}
function resultCanvas(){const c=layer(),g=c.getContext('2d');g.fillStyle='#faf7ee';g.fillRect(0,0,N,N);if(mount==='window'){g.strokeStyle='#ac7652';g.lineWidth=8;g.strokeRect(12,12,N-24,N-24);for(let i=28;i<N;i+=42){g.beginPath();g.moveTo(i,18);g.lineTo(i,N-18);g.moveTo(18,i);g.lineTo(N-18,i);g.stroke();}g.fillStyle='#faf7ee';g.fillRect(45,45,N-90,N-90);}if(mount==='fan'){g.fillStyle='#e9d6b6';g.fillRect(273,440,14,110);g.beginPath();g.arc(280,260,235,0,Math.PI*2);g.fillStyle='#fff9e8';g.fill();g.strokeStyle='#b08a5b';g.lineWidth=4;g.stroke();}g.drawImage(colored(model.keep),35,35,490,490);return c;}
function replay(){model.visited.fill(0);for(const s of strokes){let prev;for(const p of s.points){if(prev)core.segment(model,prev,p,s.tool==='knife'?10:20);else core.dab(model,p.x,p.y,s.tool==='knife'?10:20);prev=p;}}}
function render(){if(!ready)return;const p=core.progress(model);ctx.clearRect(0,0,N,N);ctx.fillStyle='#faf7ee';ctx.fillRect(0,0,N,N);
 if(stage===2){const full=resultCanvas(),amount=Math.max(.025,unfold/100);ctx.save();ctx.translate(N/2,N/2);ctx.scale(zoom/100,zoom/100);ctx.drawImage(full,280,0,280,560,0,-280,280,560);ctx.drawImage(full,0,0,280,560,-280*amount,-280,280*amount,560);if($('#crease').checked){ctx.strokeStyle='#8d715630';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-250);ctx.lineTo(0,250);ctx.stroke();}ctx.restore();}
 else {const mask=new Uint8Array(N*N).fill(1);if(stage===1)for(const r of model.regions)if(p.completed.has(r.id))for(const i of r.pixels)mask[i]=0;
  ctx.drawImage(colored(mask),0,0);
  if($('#guides').checked||stage===0){for(let i=0;i<model.points.length;i++){const pt=model.points[i];ctx.fillStyle=stage===1&&model.visited[i]?'#a8e0d0':'#fff4df9c';ctx.fillRect(pt.x,pt.y,1.5,1.5);}}
  const amount=stage===1?1:fold/100;ctx.save();ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(280*amount,20);ctx.lineTo(280*amount,540);ctx.lineTo(0,560);ctx.closePath();const grad=ctx.createLinearGradient(0,0,280,0);grad.addColorStop(0,colors[paperColor]);grad.addColorStop(1,'#7e2623');ctx.fillStyle=grad;ctx.shadowColor='#41201d55';ctx.shadowBlur=12;ctx.fill();ctx.restore();ctx.setLineDash([8,7]);ctx.strokeStyle='#fff3d8';ctx.beginPath();ctx.moveTo(280,0);ctx.lineTo(280,560);ctx.stroke();ctx.setLineDash([]);
  if(stage===0){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(280,280,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#335d51';ctx.font='17px STZhongsong';ctx.fillText('向中线拖动纸角，或调节下方滑块',55,525);}
 }
 $('#progress').value=p.percent;$('#progress-text').textContent=`${p.percent.toFixed(0)}% · 已完成 ${p.done} / ${p.total} 处`;
 $('#undo').disabled=!strokes.length;$('#action').disabled=stage===0?fold<100:stage===1?p.done<p.total:unfold<100;$('#next').disabled=$('#action').disabled;
 $('#fold-value').textContent=fold+'%';$('#unfold-value').textContent=unfold+'%';$('#zoom-value').textContent=zoom+'%';
}
function refresh(){names.forEach((name,i)=>{const b=$(`[data-stage="${i}"]`);b.setAttribute('aria-current',stage===i?'step':'false');b.querySelector('b').textContent=i<stage?'✓':i+1;});
 $('#stage-title').textContent=names[stage];$('#stage-count').textContent=`步骤 0${stage+1} / 03`;
 $('#selection-panel').hidden=stage!==0;$('#tools-panel').hidden=stage!==1;$('#mount-panel').hidden=stage!==2;$('#fold-control').hidden=stage!==0;$('#cut-control').hidden=stage!==1;$('#unfold-control').hidden=stage!==2;
 $('#action').textContent=['确认折纸','完成剪刻后展开','完成并保存'][stage];$('#next').innerHTML=stage===2?'<span aria-hidden="true">✓</span> 完成并保存':'<span aria-hidden="true">→</span> 下一步';$('#previous').disabled=stage===0;
 $('#reference-title').textContent=stage===2?'作品预览':'参考效果';$('#reference-name').textContent=pattern.name;$('#reference-description').textContent=[pattern.foldHelp,pattern.cutHelp,'一纸成花，留住手作心意。'][stage];
 $('#reference-image').src=colored(model.keep).toDataURL();$('#reference-image').alt=pattern.name+'剪纸效果';
 document.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.color===paperColor)));document.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tool===tool)));document.querySelectorAll('[data-mount]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mount===mount)));
 $('#fold-range').value=fold;$('#unfold-range').value=unfold;render();persist();
}
async function select(id){const token=++loadToken;ready=false;$('#action').disabled=$('#next').disabled=true;pattern=config.patterns.find(p=>p.id===id)||config.patterns[0];stage=0;fold=0;strokes=[];unfold=100;status('正在准备'+pattern.name+'纹样…');
 try{const img=await image(pattern.artwork);if(token!==loadToken)return;const c=layer(),g=c.getContext('2d'),scale=500/Math.max(img.width,img.height);g.drawImage(img,(N-img.width*scale)/2,(N-img.height*scale)/2,img.width*scale,img.height*scale);model=core.build(PaperCutCore.maskFromPixels(g.getImageData(0,0,N,N).data,N,N),N);if(!model.points.length)throw Error('empty');
 let saved;try{saved=JSON.parse(sessionStorage.getItem(key()));}catch{}if(saved&&Array.isArray(saved.strokes)&&saved.strokes.every(s=>['scissors','knife'].includes(s.tool)&&Array.isArray(s.points)&&s.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=280&&p.x<560&&p.y>=0&&p.y<560))){strokes=saved.strokes;paperColor=[0,1,2].includes(saved.paperColor)?saved.paperColor:0;fold=saved.fold===100?100:0;stage=fold?Math.min(2,Math.max(0,saved.stage||0)):0;mount=['paper','window','fan'].includes(saved.mount)?saved.mount:'paper';replay();if(stage===2&&core.progress(model).done<core.progress(model).total)stage=1;}
 ready=true;document.querySelectorAll('[data-pattern]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pattern===pattern.id)));history.replaceState(null,'','?pattern='+encodeURIComponent(pattern.id));refresh();status(pattern.foldHelp);
 }catch{status('纹样加载失败，请刷新后重试。');}}
function end(){pressed=false;current=null;persist();}
function cut(p){if(!ready||stage!==1||p.x<280)return;if(!current){current={tool,points:[]};strokes.push(current);}const prev=current.points.at(-1);if(prev)core.segment(model,prev,p,tool==='knife'?10:20);else core.dab(model,p.x,p.y,tool==='knife'?10:20);current.points.push({...p});render();}
function point(e){const b=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(559,(e.clientX-b.left)/b.width*N)),y:Math.max(0,Math.min(559,(e.clientY-b.top)/b.height*N))};}
canvas.onpointerdown=e=>{if(!ready||stage===2)return;pressed=true;canvas.setPointerCapture(e.pointerId);if(stage===1)cut(point(e));};canvas.onpointermove=e=>{if(!pressed)return;const p=point(e);if(stage===0){fold=Math.round(Math.min(1,p.x/280)*100);$('#fold-range').value=fold;refresh();}else cut(p);};canvas.onpointerup=end;canvas.onpointercancel=end;
canvas.onkeydown=e=>{if(!ready)return;const d={ArrowLeft:[-8,0],ArrowRight:[8,0],ArrowUp:[0,-8],ArrowDown:[0,8]};if(d[e.key]){e.preventDefault();if(stage===0){fold=Math.max(0,Math.min(100,fold+(e.key==='ArrowLeft'?-10:10)));refresh();}else{keyboard.x=Math.max(280,Math.min(559,keyboard.x+d[e.key][0]));keyboard.y=Math.max(0,Math.min(559,keyboard.y+d[e.key][1]));render();ctx.strokeStyle='#26baa1';ctx.strokeRect(keyboard.x-8,keyboard.y-8,16,16);}}if(e.key===' '&&stage===1){e.preventDefault();cut(keyboard);end();}};
function expand(){cancelAnimationFrame(anim);unfold=0;const start=performance.now();function tick(now){unfold=Math.min(100,Math.round((now-start)/12));$('#unfold-range').value=unfold;render();if(unfold<100)anim=requestAnimationFrame(tick);else persist();}anim=requestAnimationFrame(tick);}
function advance(){if(!ready||$('#action').disabled)return;end();if(stage<2){stage++;refresh();status(stage===1?pattern.cutHelp:'拖动展开滑块，查看剪纸由半幅变成完整纹样。');if(stage===2)expand();}else{const png=resultCanvas().toDataURL();const result=ArtworkStore.save({craft:'paper-cutting',name:pattern.name,patternId:pattern.id,png,savedAt:Date.now(),editState:{stage,paperColor,fold,unfold,mount,strokes}});$('#download').href=png;$('#download').download='三台剪纸-'+pattern.name+'.png';$('#download').hidden=false;status(result.ok?'作品已保存，可继续下载 PNG 或再剪一幅。':'浏览器空间不足，请点击“下载作品”保存 PNG。');}}
$('#action').onclick=$('#next').onclick=advance;$('#previous').onclick=()=>{if(stage){end();cancelAnimationFrame(anim);stage--;refresh();}};
document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const target=+b.dataset.stage;if(target<=stage){stage=target;refresh();}else advance();});
$('#fold-range').oninput=e=>{fold=+e.target.value;refresh();};$('#unfold-range').oninput=e=>{cancelAnimationFrame(anim);unfold=+e.target.value;render();persist();};$('#crease').onchange=render;$('#guides').onchange=render;
document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{paperColor=+b.dataset.color;refresh();});document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{end();tool=b.dataset.tool;refresh();});document.querySelectorAll('[data-mount]').forEach(b=>b.onclick=()=>{mount=b.dataset.mount;refresh();});
$('#undo').onclick=()=>{end();strokes.pop();replay();render();persist();};$('#recut').onclick=()=>{end();strokes=[];replay();render();persist();};$('#reset').onclick=()=>{cancelAnimationFrame(anim);end();stage=0;fold=0;unfold=100;strokes=[];replay();refresh();status('已重置当前纹样，请重新折纸。');};$('#replay').onclick=expand;$('#zoom-out').onclick=()=>{zoom=Math.max(60,zoom-10);render();};$('#zoom-in').onclick=()=>{zoom=Math.min(140,zoom+10);render();};$('#again').onclick=()=>$('#reset').click();
config.patterns.forEach(p=>{const b=document.createElement('button');b.dataset.pattern=p.id;b.innerHTML='<img alt=""><span></span><small></small>';b.querySelector('img').src=window.PAPER_CUTTING_IMAGES?.[p.artwork]||p.artwork;b.querySelector('span').textContent=p.name;b.querySelector('small').textContent=p.category;b.onclick=()=>{end();select(p.id);};$('#fold-patterns').append(b);});
window.addEventListener('pagehide',persist);window.addEventListener('blur',end);$('#credits').onclick=()=>{status('三台剪纸互动教学示意：对折、沿线剪刻、展开与装裱。纹样为本项目创作插画。');};select(new URLSearchParams(location.search).get('pattern')||'flower');
})();
